effect.shader:
void main(){
    vec2 c = center/1000.0 + 0.5;
    vec2 d = acScreenNorm - c;
    d.x *= acScreenSize.x/acScreenSize.y;
    float dist = length(d);
    float wave = sin(dist*frequency - acTime*speed) * amplitude * 0.03;
    wave *= exp(-dist*decay);
    vec2 uv = acScreenNorm + normalize(d+0.0001)*wave;
    gl_FragColor = texture2DCv(inputImg.texture, uv);
}
